#!/usr/bin/env python3
"""
compact_calendar_html_agent.py

Create a compact, standalone EEECS MAP assessment calendar HTML from the
calendar visualisation events CSV generated by calendar_visualisation_agent.py.

Default input:
  outputs/2026_27_readiness_03Sep/calendar_visual_check/MAP_Calendar_Visual_Check_Events.csv

Default output:
  outputs/2026_27_readiness_03Sep/calendar_visual_check/MAP_Calendar_2026_27.html

The output is a single local/offline HTML file with embedded CSS, JavaScript,
and compact JSON data. It does not use external libraries, fonts, CDNs,
network requests, a database, or a backend.
"""

from __future__ import annotations

import argparse
import csv
import html
import json
import re
from collections import defaultdict
from pathlib import Path
from typing import Dict, Iterable, List, Tuple, Any


